from functools import wraps


def add_interface_trace(interface):

    @wraps(interface)
    def wrappedinterface(self, *args, **kwargs):
        self.logger.debug("executing {} with args={} kwargs={}".format(interface.__name__, args, kwargs))
        response = interface(self, *args, **kwargs)
        self.logger.debug("{} response={}".format(interface.__name__, response))
        return response

    return wrappedinterface
